public class ManagerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Manager m = new Manager("Ann", 50000.0, 5000.0);
        check("getName() inherited", "Ann", m.getName());
        check("getBaseSalary() inherited", 50000.0, m.getBaseSalary());
        check("getBonus()", 5000.0, m.getBonus());
        check("pay() = base + bonus", 55000.0, m.pay());

        Employee asEmployee = new Manager("Bob", 40000.0, 2500.0);
        check("pay() through Employee reference", 42500.0, asEmployee.pay());

        Manager zero = new Manager("Cara", 30000.0, 0.0);
        check("pay() with zero bonus", 30000.0, zero.pay());

        Employee plain = new Employee("Dan", 20000.0);
        check("plain Employee pay() unchanged", 20000.0, plain.pay());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

